SELECT i.instance_id, i.proc_def_id, i.bus_id, i.starter_id, i.start_time,
       i.end_time, i.status, i.closed_by, i.close_reason, i.title
FROM wf_instance i
INNER JOIN wf_process_definition d ON i.proc_def_id = d.proc_def_id

    AND i.starter_id = #{userId}


        AND i.status = #{instanceStatus}


        AND i.status = #{query.status}


        AND d.bus_type = #{query.busType}


        AND i.instance_id = #{query.instanceId}


        AND i.title LIKE CONCAT('%', #{query.instanceTitle}, '%')


ORDER BY i.start_time DESC
